<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import {Session} from '$lib/stores';
 import AccountActionGate from './AccountActionGate.svelte';
 import PublicEntityPicker from './PublicEntityPicker.svelte';
 import UnsavedEditorGuard from './UnsavedEditorGuard.svelte';
 import {nativeAccountIssue,type NativeAccountIssue} from './native-account-scope';
 import {createNativeTeamController,type NativeTeamController,type TeamView,type TeamRequest} from './native-team-client';
 import type {EditorChoice} from './editor-fields';
 let {groupId}:{groupId:string}=$props();
 let owner=$state.raw<NativeTeamController>(),team=$state<TeamView>(),busy=$state(false),pending=$state(false),notice=$state(''),issue=$state<NativeAccountIssue>();
 let selected=$state<EditorChoice[]>([]),message=$state('');let disposed=false,epoch=0;
 onDestroy(()=>{disposed=true;epoch++;owner?.dispose();});
 async function initialize(){const token=++epoch,session=$Session,target=groupId;owner?.dispose();owner=undefined;team=undefined;issue=undefined;notice='';busy=true;pending=false;selected=[];message='';if(!session?.identity?.id){busy=false;return;}const check=()=>{if(disposed||token!==epoch||$Session!==session||groupId!==target)throw Error('The account or group changed.');};try{const next=await createNativeTeamController(session.identity.id,check);check();owner=next;team=await next.team(target);check();pending=next.pending(target);}catch(e){if(!disposed&&token===epoch){issue=nativeAccountIssue(e);notice=e instanceof Error?e.message:'Team details are unavailable.';}}finally{if(!disposed&&token===epoch)busy=false;}}
 $effect(()=>{const session=$Session,target=groupId;untrack(()=>{void session;void target;void initialize();});});
 async function reload(offset=0){if(!owner||busy)return;const current=owner,token=epoch;busy=true;try{const value=await current.team(groupId,offset);current.check();if(token===epoch)team=value;}catch(e){if(token===epoch)notice=e instanceof Error?e.message:'Could not load the team.';}finally{if(token===epoch){busy=false;pending=current.pending(groupId);}}}
 async function action(kind:'invite'|'apply'|'accept'|'decline'|'revoke'|'cancel',request?:TeamRequest){if(!owner||!team||busy||pending)return;const current=owner,token=epoch;busy=true;notice='';try{if(kind==='invite'){if(selected.length!==1)throw Error('Choose one existing account by name.');await current.invite(groupId,team.group.version,selected[0].id,message);}else if(kind==='apply')await current.apply(groupId,team.group.version,message);else{if(!request)throw Error('Choose a current request.');await current.decide(request,kind);}current.check();if(token!==epoch)return;selected=[];message='';team=await current.team(groupId);current.check();notice=kind==='invite'?'Invitation saved. The recipient can accept it in My teams. No email was sent.':kind==='apply'?'Join request sent to the group leader.':kind==='accept'?'Request accepted. Membership grants no publishing or staff permissions.':'Request updated.';}catch(e){if(!disposed&&token===epoch)notice=e instanceof Error?e.message:'The change could not be confirmed.';}finally{if(!disposed&&token===epoch){busy=false;pending=current.pending(groupId);}}}
</script>
<section class="space-y-3 rounded border p-4" aria-label="Group team">
 <h2 class="text-lg font-medium">Team membership</h2><p>Local members help with group attribution. Membership does not grant publishing, signing, or staff permissions.</p>
 <AccountActionGate {issue} onready={initialize} />
 {#if notice}<p role="status">{notice}</p>{/if}
 {#if pending}<p role="alert">An earlier team change is unconfirmed. Check the latest team below; do not send it again. Contact support if the result is still unclear.</p>{/if}
 {#if team}
  <h3 class="font-medium">{team.group.name}</h3><ul>{#each team.members as member}<li><a class="underline" href={`/user/${member.id}`}>{member.name}</a> — {member.role}</li>{/each}</ul>{#if team.hasMoreMembers}<p>Showing the first 100 members.</p>{/if}
  {#if team.canManage}<PublicEntityPicker label="Invite a member" bind:selected single search={(query,signal)=>owner!.searchUsers(query,signal)} disabled={busy||pending} /><label class="block">Message (optional)<textarea class="block w-full rounded border p-2" bind:value={message} maxlength="1000" disabled={busy||pending}></textarea></label><p class="text-sm">Invitations last seven days and can only be accepted by the selected account. They add a member, not an officer or leader.</p><button class="rounded border px-3 py-2" disabled={busy||pending||selected.length!==1} onclick={()=>action('invite')}>Send member invitation</button>
  {:else if !team.ownRole}<label class="block">Introduce yourself (optional)<textarea class="block w-full rounded border p-2" bind:value={message} maxlength="1000" disabled={busy||pending}></textarea></label><button class="rounded border px-3 py-2" disabled={busy||pending||team.requests.data.some(r=>r.kind==='application')} onclick={()=>action('apply')}>Ask to join</button>{/if}
  <UnsavedEditorGuard dirty={!!message.trim()||selected.length>0} />
  {#if team.requests.data.length}<h3 class="font-medium">Pending requests</h3>{#each team.requests.data as request(request.id)}<article class="space-y-2 rounded border p-3"><p>{request.kind==='invitation'?'Invitation for':'Join request from'} {request.username}</p>{#if request.message}<p>{request.message}</p>{/if}<p class="text-sm">Expires <time datetime={request.expiresAt}>{new Date(request.expiresAt).toLocaleString()}</time></p><div class="flex flex-wrap gap-2">{#if request.kind==='invitation'&&request.userId===owner?.account.id}<button class="rounded border px-3 py-2" disabled={busy||pending} onclick={()=>action('accept',request)}>Accept invitation</button><button class="rounded border px-3 py-2" disabled={busy||pending} onclick={()=>action('decline',request)}>Decline invitation</button>{/if}{#if request.kind==='invitation'&&team.canManage}<button class="rounded border px-3 py-2" disabled={busy||pending} onclick={()=>action('revoke',request)}>Revoke invitation</button>{/if}{#if request.kind==='application'&&team.canManage}<button class="rounded border px-3 py-2" disabled={busy||pending} onclick={()=>action('accept',request)}>Accept join request</button><button class="rounded border px-3 py-2" disabled={busy||pending} onclick={()=>action('decline',request)}>Decline join request</button>{/if}{#if request.kind==='application'&&request.userId===owner?.account.id}<button class="rounded border px-3 py-2" disabled={busy||pending} onclick={()=>action('cancel',request)}>Cancel join request</button>{/if}</div></article>{/each}{#if team.requests.hasMore}<p>There are more pending requests.</p>{/if}{/if}
  <div class="flex gap-2">{#if team.requests.offset>0}<button class="rounded border px-3 py-2" disabled={busy} onclick={()=>reload(team!.requests.offset-100)}>Previous requests</button>{/if}{#if team.requests.hasMore}<button class="rounded border px-3 py-2" disabled={busy} onclick={()=>reload(team!.requests.offset+100)}>More requests</button>{/if}<button class="rounded border px-3 py-2" disabled={busy} onclick={()=>reload()}>Refresh team</button></div>
 {:else if !busy&&$Session?.identity?.id}<button class="rounded border px-3 py-2" onclick={initialize}>Try again</button>{/if}
 <a class="block underline" href="/teams">My teams and invitations</a>
</section>
